import { test } from 'node:test';
import assert from 'node:assert/strict';
import {
  createIdempotencyStore,
  IdempotencyConflictError,
} from './idempotency.js';

const skip = createIdempotencyStore.toString().includes('TODO')
  ? 'exercise not started — remove the TODO marker to activate checks'
  : false;

test('a new command executes once and returns its result', { skip }, async () => {
  const store = createIdempotencyStore();
  let calls = 0;
  const result = await store.execute('key-1', 'POST:/orders:{sku:1}', async () => {
    calls += 1;
    return { status: 201, body: { orderId: 42 } };
  });

  assert.deepEqual(result, { status: 201, body: { orderId: 42 } });
  assert.equal(calls, 1);
});

test('a completed duplicate replays the result without rerunning work', { skip }, async () => {
  const store = createIdempotencyStore();
  let calls = 0;
  const work = async () => ({ call: ++calls });

  const first = await store.execute('same', 'same-input', work);
  const second = await store.execute('same', 'same-input', work);

  assert.deepEqual(first, { call: 1 });
  assert.deepEqual(second, { call: 1 });
  assert.equal(calls, 1);
});

test('concurrent duplicates share one in-flight operation', { skip }, async () => {
  const store = createIdempotencyStore();
  let calls = 0;
  let release;
  const gate = new Promise((resolve) => { release = resolve; });
  const work = async () => {
    calls += 1;
    await gate;
    return { ok: true };
  };

  const first = store.execute('race', 'input', work);
  const second = store.execute('race', 'input', work);
  assert.equal(calls, 1, 'the in-flight promise must be stored before awaiting it');
  release();
  assert.deepEqual(await Promise.all([first, second]), [{ ok: true }, { ok: true }]);
});

test('the same key cannot describe a different command', { skip }, async () => {
  const store = createIdempotencyStore();
  await store.execute('key-2', 'input-a', async () => ({ ok: true }));

  await assert.rejects(
    store.execute('key-2', 'input-b', async () => ({ shouldNotRun: true })),
    IdempotencyConflictError,
  );
});

test('failed work is removable and may be retried', { skip }, async () => {
  const store = createIdempotencyStore();
  let calls = 0;
  const work = async () => {
    calls += 1;
    if (calls === 1) throw new Error('temporary outage');
    return { recovered: true };
  };

  await assert.rejects(store.execute('retry', 'input', work), /temporary outage/);
  assert.deepEqual(await store.execute('retry', 'input', work), { recovered: true });
  assert.equal(calls, 2);
});

test('completed records expire according to an injected clock', { skip }, async () => {
  let time = 1_000;
  const store = createIdempotencyStore({ ttlMs: 100, now: () => time });
  let calls = 0;
  const work = async () => ({ call: ++calls });

  await store.execute('expiring', 'input', work);
  time = 1_099;
  assert.deepEqual(await store.execute('expiring', 'input', work), { call: 1 });
  time = 1_100;
  assert.deepEqual(await store.execute('expiring', 'input', work), { call: 2 });
});

test('cached objects cannot be rewritten by their callers', { skip }, async () => {
  const store = createIdempotencyStore();
  const first = await store.execute('copy', 'input', async () => ({ body: { id: 7 } }));
  first.body.id = 999;

  const replay = await store.execute('copy', 'input', async () => ({ body: { id: -1 } }));
  assert.deepEqual(replay, { body: { id: 7 } });
});

test('blank keys are rejected before work starts', { skip }, async () => {
  const store = createIdempotencyStore();
  let ran = false;
  await assert.rejects(
    store.execute('  ', 'input', async () => { ran = true; }),
    /key/i,
  );
  assert.equal(ran, false);
});

export class IdempotencyConflictError extends Error {
  constructor(key) {
    super(`idempotency key ${key} was reused for a different command`);
    this.name = 'IdempotencyConflictError';
  }
}

